-- Snapshot of patterns in lib/employment.ts, lib/experience.ts and search-plan.ts.
-- Changing those patterns requires a new migration; search-filter-flags-integration
-- compares these stored answers with the live draft expressions to detect drift.
-- Generated columns cannot reference generated columns, so repeat immutable
-- published JSON expressions from 020/027; concat_ws is deliberately avoided.
-- Run BEFORE deploying readers of these columns. One ALTER rewrites jobs under
-- ACCESS EXCLUSIVE lock (including existing rows), like migration 027.
-- The runner supplies a transaction; lock/rewrite timeout rolls everything back.
-- Rollback: revert the reader code, then ALTER TABLE jobs DROP COLUMN
-- search_entry_level, DROP COLUMN search_part_time, DROP COLUMN search_internship,
-- DROP COLUMN search_daily. No filter indexes: facet counts still scan all rows.
SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '300s';
ALTER TABLE jobs
  ADD COLUMN IF NOT EXISTS search_entry_level boolean GENERATED ALWAYS AS (
    (((lower(normalize(COALESCE(published->>'title','') || ' ' || COALESCE(published->>'company','') || ' ' || COALESCE(published->>'city','') || ' ' || COALESCE(published->>'description',''),NFKC)) || ' ' || lower(normalize(COALESCE(published->>'facts',''),NFKC))) ~ 'გამოცდილების[[:space:]]+გარეშე|გამოცდილებას[[:space:]]+(არ[[:space:]]+აქვს[[:space:]]+მნიშვნელობა|მნიშვნელობა[[:space:]]+არ[[:space:]]+აქვს)|გამოცდილება[[:space:]:–-]+(არ[[:space:]]+(არის[[:space:]]+)?(სავალდებულო|აუცილებელი|საჭირო)|არ[[:space:]]+მოითხოვება)|no[[:space:]]+(previous[[:space:]]+|prior[[:space:]]+)?experience[[:space:]]+(is[[:space:]]+)?(required|needed|necessary)|experience[[:space:]]+(is[[:space:]]+)?not[[:space:]]+(required|needed|necessary)' OR lower(normalize(COALESCE(published->>'facts',''),NFKC)) ~ '(^|[^ა-ჰ])(დამწყებ|კურსდამთავრებულ)') AND NOT (regexp_replace((lower(normalize(COALESCE(published->>'title','') || ' ' || COALESCE(published->>'company','') || ' ' || COALESCE(published->>'city','') || ' ' || COALESCE(published->>'description',''),NFKC)) || ' ' || lower(normalize(COALESCE(published->>'facts',''),NFKC))), 'არ\s+(?:უნდა|არის\s+აუცილებელი|არის\s+სავალდებულო)', '', 'g') ~ 'გამოცდილება\s+(აუცილებელია|სავალდებულოა|მოითხოვება)|(?:უნდა|აუცილებელია)\s+(?:ჰქონდეს|ქონდეს|გქონდეთ|ჰქონდეთ)\s+(?:\S+\s+){0,5}გამოცდილება'))
  ) STORED,
  ADD COLUMN IF NOT EXISTS search_part_time boolean GENERATED ALWAYS AS (
    (lower(normalize(CASE WHEN published->>'employmentType' IS NULL THEN COALESCE(published->>'title','') WHEN published->>'title' IS NULL THEN published->>'employmentType' ELSE (published->>'employmentType') || ' ' || (published->>'title') END,NFKC)) ~ '(ნახევარი?|არასრული?|ნაწილობრივი?|½|1/2)[[:space:]]*განაკვეთ|part[ -]?time' OR (lower(normalize(COALESCE(published->>'title','') || ' ' || COALESCE(published->>'company','') || ' ' || COALESCE(published->>'city','') || ' ' || COALESCE(published->>'description',''),NFKC)) ~ '(?:სამუშაო[[:blank:]]+(?:გრაფიკი|განრიგი|განაკვეთი|დატვირთვა|ფორმატი|დრო)|დასაქმების[[:blank:]]+(?:ტიპი|ფორმატი)|work[[:blank:]]+(?:hours|schedule)|employment[[:blank:]]+type)[[:blank:]:–—-]+[^\n\r.!?;]{0,100}(?:(?:ნახევარი?|არასრული?|ნაწილობრივი?|½|1/2)[[:blank:]]*განაკვეთ[ა-ჰ]*|part[ -]?time)|(?:^|[\n\r])[[:blank:]•*·>–—-]*(?:მოქნილი[[:blank:]]+)?გრაფიკ[ა-ჰ]*[[:blank:]:(–—-]+(?:(?:ნახევარი?|არასრული?|ნაწილობრივი?|½|1/2)[[:blank:]]*განაკვეთ[ა-ჰ]*|part[ -]?time)|(?:სრულ[ა-ჰ]*|full[ -]?time)[^\n\r.!?;]{0,60}(?:ან|და|ისე|ასევე|and|or|/)[[:blank:]–—-]+(?:(?:ნახევარი?|არასრული?|ნაწილობრივი?|½|1/2)[[:blank:]]*განაკვეთ[ა-ჰ]*|part[ -]?time)|(?:^|[\n\r])[[:blank:]•*·>–—-]*(?:(?:ნახევარი?|არასრული?|ნაწილობრივი?|½|1/2)[[:blank:]]*განაკვეთ[ა-ჰ]*|part[ -]?time)[[:blank:]]*(?:[:;–—(0-9-]|$|[\n\r]|გრაფიკ)|(?:^|[^ა-ჰa-z])(?:შესაძლებელია|შესაძლოა|გთავაზობთ|გვესაჭიროება|ესაჭიროება|ვეძებთ|ეძებს|იმუშაო[ა-ჰ]*|პოზიციაზე|ვაკანსია:)[^\n\r.!?;]{0,100}(?:(?:ნახევარი?|არასრული?|ნაწილობრივი?|½|1/2)[[:blank:]]*განაკვეთ[ა-ჰ]*|part[ -]?time)|(?:availability[[:blank:]]+to[[:blank:]]+work|vacancy[[:blank:]]+considers)[^\n\r.!?;]{0,40}part[ -]?time' AND lower(normalize(COALESCE(published->>'title','') || ' ' || COALESCE(published->>'company','') || ' ' || COALESCE(published->>'city','') || ' ' || COALESCE(published->>'description',''),NFKC)) !~ '(?:(?:ნახევარი?|არასრული?|ნაწილობრივი?|½|1/2)[[:blank:]]*განაკვეთ[ა-ჰ]*|part[ -]?time)[[:blank:]]+(?:არ[[:blank:]]+(?:არის|გვაქვს|განიხილება|შეგვიძლია|შეიძლება)|ვერ)|(?:არ[[:blank:]]+(?:არის[[:blank:]]+)?(?:შესაძლებელი|განიხილება)|ვერ[[:blank:]]+(?:იმუშავებ[ა-ჰ]*|გთავაზობთ))[^\n\r.!?;]{0,60}(?:(?:ნახევარი?|არასრული?|ნაწილობრივი?|½|1/2)[[:blank:]]*განაკვეთ[ა-ჰ]*|part[ -]?time)|(?:do[[:blank:]]+not|not[[:blank:]]+(?:available|offered))[^\n\r.!?;]{0,30}part[ -]?time'))
  ) STORED,
  ADD COLUMN IF NOT EXISTS search_internship boolean GENERATED ALWAYS AS (
    (lower(normalize(CASE WHEN published->>'employmentType' IS NULL THEN COALESCE(published->>'title','') WHEN published->>'title' IS NULL THEN published->>'employmentType' ELSE (published->>'employmentType') || ' ' || (published->>'title') END,NFKC)) ~ 'სტაჟიორ|სტაჟირებ|\mintern(ship)?\M' OR lower(normalize(COALESCE(published->>'title','') || ' ' || COALESCE(published->>'company','') || ' ' || COALESCE(published->>'city','') || ' ' || COALESCE(published->>'description',''),NFKC)) ~ '(?:აცხადებს|ვაცხადებთ)[[:blank:]]+(?:ანაზღაურებად[[:blank:]]+)?სტაჟირებ|(?:აცხადებს|ვაცხადებთ)[[:blank:]]+ვაკანსიას[^\n\r.!?;]{0,100}სტაჟიორ[ა-ჰ]*[[:blank:]]+პოზიცია|(?:ვეძებთ|ეძებს|ესაჭიროება|გვჭირდება)[[:blank:]]+(?:[ა-ჰa-z]+[[:blank:]]+){0,4}სტაჟიორ|დასაქმების[[:blank:]]+ტიპი[[:blank:]:–—-]+სტაჟირებ|(?:we[[:blank:]]+are[[:blank:]]+(?:hiring|seeking)|looking[[:blank:]]+for)[[:blank:]]+(?:(?:an?|paid|unpaid)[[:blank:]]+)?intern\M')
  ) STORED,
  ADD COLUMN IF NOT EXISTS search_daily boolean GENERATED ALWAYS AS (
    ((lower(normalize(CASE WHEN published->>'employmentType' IS NULL THEN COALESCE(published->>'title','') WHEN published->>'title' IS NULL THEN published->>'employmentType' ELSE (published->>'employmentType') || ' ' || (published->>'title') END,NFKC)) || ' ' || lower(normalize(COALESCE(published->>'title','') || ' ' || COALESCE(published->>'company','') || ' ' || COALESCE(published->>'city','') || ' ' || COALESCE(published->>'description',''),NFKC))) ~ '(^|[^ა-ჰa-z])(დღიური|ერთდღიანი|ერთჯერადი)[[:blank:]-]+(სამუშაო|სამსახური|დასაქმება|მუშა|მშრომელ)([^ა-ჰa-z]|$)|one[ -]day[[:blank:]]+(job|work)\M|day[ -]labou?r\M')
  ) STORED;
ANALYZE jobs;
